/bin/bash -lc "cat > /tmp/caught-up-check.cjs <<'JS'
const {spawn}=require('node:child_process');
const fs=require('node:fs');
const chrome=spawn('/root/.cache/ms-playwright/chromium-1140/chrome-linux/chrome',['--headless','--no-sandbox','--no-zygote','--single-process','--disable-dev-shm-usage','--disable-gpu','--disable-crashpad-for-testing','--remote-debugging-pipe','--user-data-dir=/tmp/caught-up-chrome','about:blank'],{stdio:['ignore','ignore','ignore','pipe','pipe']});
let id=0,buf='',pending=new Map();
chrome.stdio[4].on('data',b=>{buf+=b;let i;while((i=buf.indexOf('\\0'))>=0){const m=JSON.parse(buf.slice(0,i));buf=buf.slice(i+1);if(pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}}});
function send(method,params={},sessionId){return new Promise((resolve,reject)=>{const n=++id;pending.set(n,resolve);chrome.stdio[3].write(JSON.stringify({id:n,method,params,...(sessionId?{sessionId}:{})})+'\\0');setTimeout(()=>reject(Error(method)),10000).unref();});}
(async()=>{
const t=await send('Target.createTarget',{url:'about:blank'});const a=await send('Target.attachToTarget',{targetId:t.result.targetId,flatten:true});const s=a.result.sessionId;
await send('Page.enable',{},s);
await send('Emulation.setDeviceMetricsOverride',{width:160,height:128,deviceScaleFactor:2,mobile:false},s);
await send('Page.navigate',{url:'file://'+process.cwd()+'/caught-up.svg'},s);
await new Promise(r=>setTimeout(r,300));
for(const time of [0,3500]){
const result=await send('Runtime.evaluate',{expression:"'`document.getAnimations().forEach(a=>{a.pause();a.currentTime=${time}});getComputedStyle(document.querySelector('"'.mail')).transform"'`,returnByValue:true},s);console.log(time,result.result.result.value);
const shot=await send('"'Page.captureScreenshot',{format:'png'},s);fs.writeFileSync('/tmp/caught-up-'+time+'.png',Buffer.from(shot.result.data,'base64'));
}
await send('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]},s);
const reduced=await send('Runtime.evaluate',{expression:\"getComputedStyle(document.querySelector('.mail')).animationName\",returnByValue:true},s);console.log('Reduced motion:',reduced.result.result.value);
await send('Browser.close');
})().catch(e=>{console.error(e);chrome.kill();process.exitCode=1;});
